# (mirrors compute.MIN_CREDIBLE_W_PRIME_J, copied so this migration never changes).
MIN_CREDIBLE_W_PRIME_J = 1_000


def copy_cp_and_w_prime(apps, schema_editor):
    """Give riders already on plans their Zwift Racing CP and W′.

    New riders get them when they are added; these were added before the planner knew
    about W′. Only blanks are filled, and only from today's Zwift Racing record, which is
    the best value there is: the rest of their snapshot (weight, height, FTP) stays as it
    was.
    """
    PlanRider = apps.get_model("ttt_planner", "PlanRider")
    ZRRider = apps.get_model("zwiftracing", "ZRRider")
    riders = list(PlanRider.objects.filter(zwid__isnull=False, cp_w__isnull=True, w_prime_j__isnull=True))
    if not riders:
        return
    power = {
        zr.zwid: (zr.power_cp, zr.power_awc)
        for zr in ZRRider.objects.filter(zwid__in={r.zwid for r in riders}).only("zwid", "power_cp", "power_awc")
    }
    changed = []
    for rider in riders:
        cp, awc = power.get(rider.zwid, (None, None))
        if cp and cp > 0:
            rider.cp_w = round(cp)
        if awc and awc >= MIN_CREDIBLE_W_PRIME_J:
            rider.w_prime_j = round(awc)
        if rider.cp_w or rider.w_prime_j:
            changed.append(rider)
    PlanRider.objects.bulk_update(changed, ["cp_w", "w_prime_j"])


